public static char[] toPrimitive(final Character[] array) {
  // Handle null array input
  if (array == null) {
    return null;
  }

  // Create a new char array to store the primitive values
  char[] primitiveArray = new char[array.length];

  // Iterate over the Character array and populate the primitiveArray
  for (int i = 0; i < array.length; i++) {
    // Check if the current element is null
    if (array[i] == null) {
      throw new NullPointerException("Array contains null content");
    }
    // Add the primitive value to the primitive array
    primitiveArray[i] = array[i].charValue();
  }

  // Return the primitive array
  return primitiveArray;
}

