    int length = 0;

    // UTF-8 byte 1 is special - we don't need to read the next byte if the first byte is 00~07F
    int utf8Byte1 = utfBuffer[constantPoolEntryIndex];
    if (utf8Byte1 < 0) {
        utf8Byte1 &= 0xFF;
