    if (utf8Byte1 < 0x80) {
        utf16[0] = utf8Byte1;
        length = 1;
    } else {
        // first byte is >= 0x80, the next byte is the continuation of the character
        utf16[0] = (utf8Byte1 & 0x3F) << 6;
        int utf8Byte2 = utfBuffer[constantPoolEntryIndex + 1];
        if (utf8Byte2 < 0) {
            utf8Byte2 &= 0xFF;
