/**
 * Generates a string that is longest common subsequence between two input strings
 *
 * @param x the first input string
 * @param y the second input string
 * @return the longest common subsequence string between the two input strings
 */
public static String lcs(String x, String y) {
    int m = x.length();
    int n = y.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (x.charAt(i - 1) == y.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    int i = m, j = n;
    char[] lcs = new char[dp[m][n]];
    while (i > 0 && j > 0) {
        if (x.charAt(i - 1) == y.charAt(j - 1)) {
            lcs[dp[i][j] - 1] = x.charAt(i - 1);
            i--;
            j--;
        } else if (dp[i][j] == dp[i][j - 1]) {
            j--;
        } else {
            i--;
        }
    }
    StringBuilder output = new StringBuilder();
    for (int k = 0; k < lcs.length; k++) {
        output.append(lcs[k]);
    }
    return output.toString();
}

