public static final <V> void reverse(V[] arr, int from, int to) {
    // Check if the range is valid
    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid 'from' index: " + from);
    }
    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid 'to' index: " + to);
    }
    if (from > to) {
        throw new IllegalArgumentException("'from' index cannot be greater than 'to' index");
    }

    // Reverse the range of elements
    for (int i = from, j = to; i < j; i++, j--) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

