private static String unescapeJava(String str) throw Exception {
String unescapedStr = "";
for (int i = 0; i < str.length(); i++) {
  if (str.charAt(i) == '\\') {
    i++;
    if (i == str.length()) {
      throw new Exception("Illegal escape sequence");
    }
    switch (str.charAt(i)) {
      case 'n': unescapedStr += "\n"; break;
      case 'r': unescapedStr += "\r"; break;
      case 't': unescapedStr += "\t"; break;
      case '\'': unescapedStr += '\''; break;
      case '\"': unescapedStr += '\"'; break;
      case '\\': unescapedStr += "\\"; break;
      default: unescapedStr += "\\" + str.charAt(i); break;
    }
  } else {
    unescapedStr += str.charAt(i);
  }
}
return unescapedStr;
}

