public int removeUnusedNodes() {
	int numUnusedNodes = 0;
	Set<CategoryNode> inactiveNodes = new HashSet<>();

	// Iterate through the Category tree and get all nodes with no children or whose child
	// is not a status message
	for (CategoryNode node : categoryTree.values()) {
		if (node.isActive()) {
			continue;
		}

		inactiveNodes.add(node);
	}

	// Remove all inactive nodes from the Category tree
	for (CategoryNode node : inactiveNodes) {
		categoryTree.remove(node);
		numUnusedNodes++;
	}

	return numUnusedNodes;
}

