        throw new IllegalArgumentException("Time range must be positive!");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start must be smaller than or equal to end!");
    }
    if ((end - start) / TimeUnit.MINUTES.toMinutes(FETCH_DATA_DURATION) > 1) {
        throw new IllegalArgumentException("Time range must be smaller than or equal to " + FETCH_DATA_DURATION + " minutes!");
    }
    for (long i = 0; i < FETCH_DATA_DURATION; i += FETCH_DATA_DURATION) {
        TimeRange timeRange = new TimeRange(i * TimeUnit.MINUTES.toMillis(FETCH_DATA_DURATION), (i + 1) * TimeUnit.MINUTES.toMillis(FETCH_DATA_DURATION));
        if (timeRange.getStart() > start && timeRange.getStart() < end) {
            timeRanges.add(timeRange);
        }
    }
    return timeRanges;
}

